import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const session: ChatSession = {
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
};

const provider: AIProvider = {
  async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hello'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
};

describe('beforeSession cleanup', () => {
  it('runs afterSession when beforeSession throws', async () => {
    const failure = new Error('setup failed');
    let afterSessionRan = false;
    const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'HAL'}), undefined, {
      hooks: {
        beforeSession: async () => {
          throw failure;
        },
        afterSession: async () => {
          afterSessionRan = true;
        },
      },
    });

    await expect(orchestrator.processMessage(session)).rejects.toBe(failure);
    expect(afterSessionRan).toBe(true);
  });
});
EOF
